import { prisma } from "@/lib/prisma";
import { getConnector } from "@/lib/marketplace/connectors";
import { startSyncLog, finalizeSyncLog, failSyncLog } from "@/lib/marketplace/sync-log";
import type { MarketplacePlatform } from "@/lib/marketplace/types";
import { markMarketplaceListingsSold } from "@/lib/marketplace/close-listings";

function safeJson(value: unknown): string | null {
  try {
    return value == null ? null : JSON.stringify(value);
  } catch {
    return null;
  }
}

export interface OrderSyncResult {
  scanned: number;
  created: number;
  updated: number;
  skipped: number;
  failed: number;
  errors: string[];
}

/**
 * Idempotent marketplace order sync. Uses (marketplace, marketplaceOrderId) as
 * the idempotency key so re-running the sync never duplicates orders or items.
 */
export async function syncOrdersForPlatform(
  shopId: string,
  params: { from?: string; limit?: number; offset?: number } = {}
): Promise<OrderSyncResult> {
  const shop = await prisma.marketplaceShop.findUnique({
    where: { id: shopId },
    include: { connection: true },
  });
  if (!shop || shop.status !== "CONNECTED" || shop.connection.status !== "CONNECTED") {
    throw new Error("Marketplace shop is not connected.");
  }
  const platform = shop.marketplace as MarketplacePlatform;
  const connector = getConnector(platform);
  if (!connector) throw new Error(`No connector registered for ${platform}`);

  const logId = await startSyncLog(platform, "ORDERS", "SYSTEM", shop.id);
  const counters = { scanned: 0, created: 0, updated: 0, skipped: 0, failed: 0 };
  const errors: string[] = [];

  try {
    const orders = await connector.fetchOrders(params, {
      connectionId: shop.connectionId,
      shopId: shop.id,
      externalShopId: shop.externalShopId,
      shopName: shop.name,
    });
    counters.scanned = orders.length;

    for (const order of orders) {
      if (!order.orderId) {
        counters.skipped += 1;
        continue;
      }
      try {
        const existing = await prisma.marketplaceOrder.findFirst({
          where: {
            marketplace: order.marketplace,
            marketplaceShopId: shop.id,
            marketplaceOrderId: order.orderId,
          },
        });

        const orderData = {
          marketplace: order.marketplace,
          marketplaceShopId: shop.id,
          marketplaceOrderId: order.orderId,
          orderNumber: order.orderNumber,
          marketplaceShopName: order.shopName ?? null,
          status: order.status || "IMPORTED",
          buyerName: order.buyerName ?? null,
          buyerEmail: order.buyerEmail ?? null,
          buyerCountry: order.buyerCountry ?? null,
          buyerCity: order.buyerCity ?? null,
          buyerState: order.buyerState ?? null,
          buyerZip: order.buyerZip ?? null,
          trackingCode: order.trackingCode || existing?.trackingCode || null,
          carrier: order.carrier || existing?.carrier || null,
          orderTotal: order.orderTotal,
          currency: order.currency || "USD",
          orderDate: order.orderDate,
          rawMetadata: safeJson(order.raw),
          lastSyncedAt: new Date(),
        };

        let orderId: string;
        if (existing) {
          orderId = existing.id;
          await prisma.marketplaceOrder.update({ where: { id: existing.id }, data: orderData });
          counters.updated += 1;
        } else {
          const created = await prisma.marketplaceOrder.create({ data: orderData });
          orderId = created.id;
          counters.created += 1;
        }

        for (const item of order.items) {
          const itemId = item.itemId;
          const where = itemId
            ? { orderId_marketplaceItemId: { orderId, marketplaceItemId: itemId } }
            : undefined;

          if (!where) {
            counters.skipped += 1;
            continue;
          }

          const inventory = item.sku ? await prisma.inventory.findUnique({ where: { sku: item.sku }, select: { id: true } }) : null;
          const itemData = {
            orderId,
            marketplaceItemId: itemId,
            listedSku: item.sku,
            listedTitle: item.title,
            quantity: item.quantity,
            unitPrice: item.unitPrice,
            currency: item.currency || order.currency || "USD",
            inventoryId: inventory?.id || null,
            status: inventory ? "MATCHED" : item.sku ? "UNKNOWN_SKU" : "NO_SKU",
            rawMetadata: safeJson(item.raw),
          };

          const existingItem = await prisma.marketplaceOrderItem.findUnique({ where });
          if (existingItem) {
            await prisma.marketplaceOrderItem.update({ where: { id: existingItem.id }, data: itemData });
          } else {
            await prisma.marketplaceOrderItem.create({ data: itemData });
          }
        }

        const listingIds = order.items.map((item) => item.listingId).filter((id): id is string => Boolean(id));
        const inventoryIds = [...new Set(
          (await prisma.marketplaceOrderItem.findMany({
            where: { orderId, inventoryId: { not: null } },
            select: { inventoryId: true },
          })).map((item) => item.inventoryId).filter((id): id is string => Boolean(id))
        )];
        await markMarketplaceListingsSold({
          marketplace: order.marketplace,
          marketplaceShopId: shop.id,
          externalIds: listingIds,
          inventoryIds,
        });
      } catch (error) {
        counters.failed += 1;
        const message = error instanceof Error ? error.message : String(error);
        errors.push(`${order.orderId}: ${message}`);
        console.error(`[sync-orders] failed for ${platform} ${order.orderId}:`, error);
      }
    }

    await finalizeSyncLog(logId, {
      status: counters.failed > 0 ? "PARTIAL" : "SUCCESS",
      counters,
      errorDetails: errors.length ? errors.slice(0, 20).join("\n").slice(0, 4000) : null,
    });
    return { ...counters, errors };
  } catch (error) {
    await failSyncLog(logId, error);
    throw error;
  }
}
